<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { copy } from './input-preferences';
  interface Preferences {log_level:'error'|'warn'|'info'|'debug'|'trace';show_fps:boolean;show_damage_regions:boolean;show_input_events:boolean;verbose_protocol_logs:boolean}
  interface Snapshot {preferences:Preferences;defaults:Preferences;log_path:string|null;diagnostics:string}
  const switches=[['show_fps','Log FPS / frame timing','Log frame pacing information.'],['show_damage_regions','Log damage regions','Log compositor damage-region statistics.'],['show_input_events','Log input events','Log pointer and keyboard event traces.'],['verbose_protocol_logs','Verbose Wayland/XWayland logs','Enable extra protocol logging where available.']] as const;
  let saved=$state<Preferences|null>(null),draft=$state<Preferences|null>(null),defaults=$state<Preferences|null>(null),logPath=$state<string|null>(null),diagnostics=$state(''),busy=$state(false),loading=$state(true),error=$state(''),message=$state(''),resetPending=$state(false);
  let alive=true;
  let dirty=$derived(!!saved&&!!draft&&JSON.stringify(draft)!==JSON.stringify(saved));
  function accept(next:Snapshot){saved=copy(next.preferences);draft=copy(next.preferences);defaults=copy(next.defaults);logPath=next.log_path;diagnostics=next.diagnostics;resetPending=false;}
  async function reload(){busy=true;error='';message='';try{const next=await invoke<Snapshot>('get_debug');if(alive)accept(next);}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;loading=false;}}}
  function discard(){if(saved)draft=copy(saved);error='';message='';resetPending=false;}
  async function apply(){if(!saved||!draft||busy)return;busy=true;error='';message='';try{const next=await invoke<{snapshot:Snapshot;message:string}>('apply_debug',{change:{expected:copy(saved),requested:copy(draft)}});if(alive){accept(next.snapshot);message=next.message;}}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  async function action(command:'open_debug_log'|'copy_debug_diagnostics'){busy=true;error='';message='';try{const result=await invoke<string>(command);if(alive)message=result;}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  onMount(()=>{void reload();return()=>{alive=false;};});
</script>
<div class="page-heading"><div><div class="eyebrow">UNDERSTAND YOUR DESKTOP</div><h1>Debug</h1><p>Adjust logging and prepare local diagnostics for a bug report.</p></div><button class="quiet" disabled={busy} onclick={reload}>Reload diagnostics</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}
{#if loading}<div class="loading" role="status">Reading diagnostic preferences…</div>{:else if draft}
<fieldset disabled={busy}><legend class="sr-only">Debug preferences</legend><section class="section"><h2>Diagnostics</h2><p class="description">Choose how much detail the desktop session records.</p><div class="settings-card"><div class="setting-row"><div><label for="debug-level">Log level</label><p>Runtime logging detail for the desktop session.</p></div><select id="debug-level" bind:value={draft.log_level}>{#each ['error','warn','info','debug','trace'] as level}<option value={level}>{level[0].toUpperCase()+level.slice(1)}</option>{/each}</select></div>{#each switches as [key,label,description]}<div class="setting-row"><div><label for={`debug-${key}`}>{label}</label><p>{description}</p></div><input id={`debug-${key}`} class="switch" type="checkbox" role="switch" bind:checked={draft[key]} /></div>{/each}</div></section>
<section class="section"><h2>Files and report details</h2><p class="description">Reports include version, session details, and local paths. Review the preview before sharing. Log contents are opened separately in your default application.</p><div class="settings-card"><div class="setting-row"><div><strong>Session log</strong><p class="log-path">{logPath??'No FocalDesk log file was found.'}</p></div><button class="quiet" disabled={!logPath} onclick={()=>action('open_debug_log')}>Open log file</button></div><div class="setting-row"><div><label for="debug-report">Diagnostic preview</label><p>Generated locally. Copying does not upload or send this report.</p></div><button class="quiet" onclick={()=>action('copy_debug_diagnostics')}>Copy diagnostics</button></div><textarea id="debug-report" readonly value={diagnostics} aria-label="Diagnostic report preview" spellcheck="false"></textarea></div></section>
<section class="section"><h2>Restore diagnostic defaults</h2><p class="description">Return to Info logging and turn off the extra tracing switches in your draft.</p><button class="quiet" onclick={()=>resetPending=true}>Reset debug settings</button>{#if resetPending}<div class="reset-prompt" role="group" aria-label="Confirm debug reset"><p>Restore diagnostic defaults in this draft? Apply to save.</p><button class="quiet" onclick={()=>resetPending=false}>Keep debug settings</button><button class="quiet" onclick={()=>{if(defaults)draft=copy(defaults);resetPending=false;}}>Reset debug draft</button></div>{/if}</section></fieldset>
<footer class="apply-bar"><div><span class="status-dot" class:unsaved={dirty}></span>{dirty?'You have unapplied debug changes':'Debug preferences match the saved configuration'}</div><div class="apply-actions"><button class="quiet" disabled={busy||!dirty} onclick={discard}>Discard debug changes</button><button class="primary" disabled={busy||!dirty} onclick={apply}>Apply debug changes</button></div></footer>
{/if}
<style>fieldset{padding:0;margin:0;border:0;min-width:0}.description{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0 18px}select{font:inherit;font-size:12px;border:1px solid var(--fd-border);border-radius:8px;padding:10px;background:var(--fd-surface);color:var(--fd-text);min-width:120px}.setting-row>div{min-width:0}.log-path{overflow-wrap:anywhere;user-select:text}strong{font-size:13px}textarea{display:block;box-sizing:border-box;width:100%;min-height:310px;resize:vertical;padding:20px;border:0;border-top:1px solid var(--fd-border);background:var(--fd-surface);color:var(--fd-text-muted);font:11px/1.9 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.reset-prompt{padding:20px;border:1px solid var(--fd-border);border-radius:var(--fd-radius);margin-top:18px}.reset-prompt p{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin-bottom:12px}.reset-prompt button{margin-right:8px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}</style>
